def connect(self):
        response = self.send_command("io.connect")
        if response.get("success"):
            self.connected = True
        return response

% Read response
response = read(t);
data = jsondecode(char(response));

% Close
clear t;
```

**Docker/Container Usage:**
```bash
# Expose host's Serial Studio to container
docker run -it --network host my-automation-script

# Inside container, connect to 127.0.0.1:7777
```

### Custom Protocol Wrappers

Build language-specific wrappers for easier use:

```python
class SerialStudio:
    def __init__(self, host='127.0.0.1', port=7777):
        self.api = SerialStudioAPI(host, port)

def uart(self):
        return UARTDriver(self.api)

def network(self):
        return NetworkDriver(self.api)

class UARTDriver:
    def __init__(self, api):
        self.api = api

def set_baud_rate(self, rate):
        return self.api.send("io.uart.setBaudRate", {"baudRate": rate})

def get_ports(self):
        response = self.api.send("io.uart.listPorts")
        return response.get("result", {}).get("portList", [])

# Usage
ss = SerialStudio()
ss.uart().set_baud_rate(115200)
ports = ss.uart().get_ports()
```

## MCP (Model Context Protocol) Integration

Serial Studio includes a built-in **MCP (Model Context Protocol) server** that exposes the API Server functionality to AI models like Claude and ChatGPT. AI assistants can control Serial Studio directly (connecting to devices, reading sensor data, sending commands, and managing exports) through natural language instructions.

```json
"sounds": {
  "sequence": "M",
  "channels": {
    "Engine": { "warning": "sounds/horn.wav", "caution": "sounds/chime.wav" }
  }
}
```

A relative path resolves against the project file's folder, so a project folder can be shared with its sounds. A file that no longer exists falls back to the bundled sound and raises a Problem Center warning naming the path.

## API

## Script structure

A Canvas script defines two functions: `paint()` (required) and `onFrame()` (optional).

```javascript
// Minimal example: a single bar that follows datasets[0].
function paint(ctx, w, h) {
  ctx.fillStyle = "#f5f5f1";
  ctx.fillRect(0, 0, w, h);

if (datasets.length === 0) return;

const ds = datasets[0];
  const v  = (ds.value - ds.min) / (ds.max - ds.min || 1);

ctx.fillStyle = "#10b981";
  ctx.fillRect(8, h - v * (h - 16) - 8, w - 16, v * (h - 16));
}
```

### `paint(ctx, w, h)`

Called every UI tick. The bitmap is cleared to transparent before the call, and the path is empty. All other context state (`fillStyle`, `strokeStyle`, `font`, `globalAlpha`, transform, line styles) persists from the previous frame. Set every property on which the frame depends at the top of `paint()`, or wrap mid-frame changes in `save()` / `restore()` pairs.

`onFrame()` is the place for time-domain bookkeeping: pushing samples into history buffers, decaying peak holds, integrating a phase angle. Keeping that logic out of `paint()` makes both functions easier to read and review.

```javascript
const HISTORY = 256;
const trace   = [];

function onFrame() {
  if (datasets.length === 0) return;
  trace.push(datasets[0].value);
  if (trace.length > HISTORY) trace.shift();
}

function paint(ctx, w, h) {
  ctx.fillStyle = "#06140a";
  ctx.fillRect(0, 0, w, h);

if (trace.length < 2) return;

ctx.strokeStyle = "#22c55e";
  ctx.lineWidth   = 2;
  ctx.beginPath();
  for (let i = 0; i < trace.length; ++i) {
    const x = (i / (HISTORY - 1)) * w;
    const y = h - (trace[i] / 100) * h;
    i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
  }
  ctx.stroke();
}
```

```javascript
var alarmRaised = false;
function onFrame() {
  var high = datasets[0].value > 100;
  if (high && !alarmRaised) actionFire(7);   // existing "Alarm" action
  alarmRaised = high;
}
```

The dashboard helpers (`clearPlots()`, `setPlotPoints(n)`, `setTerminalVisible(bool)`, `setNotificationLogVisible(bool)`, `setClockVisible(bool)`, `setStopwatchVisible(bool)`, `setActiveWorkspace(idOrName)`) are also available, with the same `{ ok, error }` return shape and the same "fire once on a state transition" guidance. Do not call them from `paint()`.

See [Frame Parser Scripting](Frame-Parser.md) for full signatures and failure modes shared across parsers, transforms, and canvas scripts.

```javascript
ctx.beginPath();
ctx.moveTo(cx + Math.cos(startA) * r, cy + Math.sin(startA) * r);
ctx.arc(cx, cy, r, startA, endA);
ctx.stroke();
```

For full circles, `moveTo(cx + r, cy)` is sufficient.

### Direct shapes

`fillRect(x, y, w, h)`, `strokeRect(x, y, w, h)`, `clearRect(x, y, w, h)`. These bypass the path and are appropriate for backgrounds and grids.

### Text

`fillText(text, x, y)`, `strokeText(text, x, y)`, `measureTextWidth(text)`, `measureText(text)`. Honors the current `font`, `textAlign`, and `textBaseline`. `measureTextWidth` returns the advance width as a plain number; `measureText` returns a metrics object with `width`, `actualBoundingBoxAscent`, `actualBoundingBoxDescent`, `fontBoundingBoxAscent`, and `fontBoundingBoxDescent`.

A card with a soft shadow and a 1-pixel border holds the content:

```javascript
const pad = 14;
ctx.fillStyle = theme.widget_border;      // shadow
ctx.fillRect(pad + 1, pad + 2, w - pad * 2, h - pad * 2);
ctx.fillStyle = theme.alternate_base;     // card body
ctx.fillRect(pad, pad, w - pad * 2, h - pad * 2);
ctx.strokeStyle = theme.widget_border;
ctx.lineWidth = 1;
ctx.strokeRect(pad + 0.5, pad + 0.5, w - pad * 2 - 1, h - pad * 2 - 1);
```

The 0.5-pixel offset on `strokeRect` aligns the stroke to a single pixel column. See "Lines look fuzzy" under [Common errors](#common-errors).

### Header strip

A header consists of a left-aligned bold title, an optional right-aligned secondary label, and a 1-pixel rule:

```javascript
ctx.fillStyle = theme.widget_text;
ctx.font = "bold 11px sans-serif";
ctx.textAlign = "start";
ctx.fillText("LEVEL  METER", pad + 16, headerY + 4);

ctx.fillStyle = theme.placeholder_text;
ctx.font = "9px sans-serif";
ctx.textAlign = "end";
ctx.fillText(datasets.length === 1 ? datasets[0].title : "MULTI",
             w - pad - 16, headerY + 4);

ctx.fillStyle = theme.widget_border;
ctx.fillRect(pad + 12, headerY + 12, w - (pad + 12) * 2, 1);
```

The double space in `"LEVEL  METER"` widens the inter-letter spacing without requiring a font change. The right-aligned label falls back to a fixed tag when the template draws more than one dataset in a single meter.

### Segmented bars

The templates draw bars as a sequence of solid-color segments rather than a gradient fill. Each segment is rendered in one of two states (lit or unlit) so the full range of the bar remains visible:

```javascript
const SEGMENTS = 32;
const SEG_GAP  = 2;
const segW = (w - SEG_GAP * (SEGMENTS - 1)) / SEGMENTS;
for (let i = 0; i < SEGMENTS; ++i) {
  const t   = (i + 0.5) / SEGMENTS;
  const lit = t <= level;
  ctx.fillStyle = lit ? lit_color(t) : unlit_color(t);
  ctx.fillRect(x + i * (segW + SEG_GAP), y, segW, h);
}
```

`lit_color(t)` and `unlit_color(t)` pick from `theme.widget_highlight`, `theme.accent`, and `theme.alarm` by zone, and from `theme.widget_border` when unlit. The dial gauge and progress rings templates apply the same approach to colored arc zones.

To place a value and a unit label side by side, measure the value with the value's own font:

```javascript
ctx.font = "bold 18px sans-serif";
const valueW = ctx.measureTextWidth(value);
ctx.fillText(value, x, y);

ctx.fillStyle = theme.placeholder_text;
ctx.font      = "10px sans-serif";
ctx.fillText(units, x + valueW + 6, y);
```

For centered text, prefer `textAlign` over a measured offset:

```javascript
ctx.textAlign = "center";
ctx.fillText(label, cx, y);
```

### Light and dark themes

Every bundled template, including the instrument-style ones (`oscilloscope`, `radar_sweep`, `horizon`), draws through the same `theme` object; none of them hardcode a light or dark palette. The "instrument panel" look on those three comes from the composition — a recessed screen with a scan grid inside the same card frame — not from a separate color scheme, so the panel repaints correctly in whichever theme the user has active. A Canvas that reads `theme.*` gets the same behavior for free.

### Sizing

Compute the available area first, fit content into the smaller dimension, and center horizontally. Hard-coded fractional positions like `cy = h * 0.55` look correct at one aspect ratio and break at others.

```javascript
const labelH = 36;                          // reserved for bottom labels
const margin = 12;
const availW = w - margin * 2;
const availH = h - margin * 2 - labelH;
const r      = Math.max(8, Math.min(availW, availH) * 0.5 - 8);
const cx     = w / 2;
const cy     = margin + r + 8;
```

## Examples

### Sparkline

A 60-sample rolling trace with a filled area and a marker at the latest sample.

```javascript
const HISTORY = 60;
const trace   = [];

function onFrame() {
  if (datasets.length === 0) return;
  const v = datasets[0].value;
  if (Number.isFinite(v)) {
    trace.push(v);
    if (trace.length > HISTORY) trace.shift();
  }
}

function paint(ctx, w, h) {
  ctx.fillStyle = theme.widget_base;
  ctx.fillRect(0, 0, w, h);

if (trace.length < 2) return;

const ds    = datasets[0];
  const span  = (ds.max - ds.min) || 1;
  const color = theme.widget_highlight;

// Filled area under the line.
  ctx.fillStyle   = color;
  ctx.globalAlpha = 0.18;
  ctx.beginPath();
  ctx.moveTo(0, h);
  for (let i = 0; i < trace.length; ++i) {
    const x = (i / (HISTORY - 1)) * w;
    const n = (trace[i] - ds.min) / span;
    const y = h - Math.max(0, Math.min(1, n)) * h;
    ctx.lineTo(x, y);
  }
  ctx.lineTo(((trace.length - 1) / (HISTORY - 1)) * w, h);
  ctx.closePath();
  ctx.fill();
  ctx.globalAlpha = 1;

// Line on top of the fill.
  ctx.strokeStyle = color;
  ctx.lineWidth   = 1.5;
  ctx.beginPath();
  for (let i = 0; i < trace.length; ++i) {
    const x = (i / (HISTORY - 1)) * w;
    const n = (trace[i] - ds.min) / span;
    const y = h - Math.max(0, Math.min(1, n)) * h;
    if (i === 0) ctx.moveTo(x, y);
    else         ctx.lineTo(x, y);
  }
  ctx.stroke();
}
```

### Tank level with alarm coloring

Renders one dataset as a segmented vertical fill. The fill color switches through green, amber, and red based on the dataset's alarm thresholds.

```javascript
function paint(ctx, w, h) {
  ctx.fillStyle = theme.widget_base;
  ctx.fillRect(0, 0, w, h);

if (datasets.length === 0) return;

const ds   = datasets[0];
  const v    = Number.isFinite(ds.value) ? ds.value : ds.min;
  const span = (ds.max - ds.min) || 1;
  const norm = Math.max(0, Math.min(1, (v - ds.min) / span));

// Card with header.
  const pad = 16;
  ctx.fillStyle = theme.alternate_base;
  ctx.fillRect(pad, pad + 22, w - pad * 2, h - pad * 2 - 22);
  ctx.strokeStyle = theme.widget_border;
  ctx.lineWidth = 1;
  ctx.strokeRect(pad + 0.5, pad + 22 + 0.5, w - pad * 2 - 1, h - pad * 2 - 23);

ctx.fillStyle = theme.widget_text;
  ctx.font = "bold 11px sans-serif";
  ctx.textAlign = "start";
  ctx.fillText("TANK  LEVEL", pad, 18);
  ctx.fillStyle = theme.placeholder_text;
  ctx.font = "9px sans-serif";
  ctx.textAlign = "end";
  ctx.fillText(ds.units || "", w - pad, 18);

// Tank body.
  const tx = pad + 24;
  const ty = pad + 36;
  const tw = w - pad * 2 - 48;
  const th = h - ty - pad - 28;

ctx.fillStyle = theme.alternate_base;
  ctx.fillRect(tx, ty, tw, th);

// Color selection based on alarms.
  let color = theme.widget_highlight;
  if (Number.isFinite(ds.alarmHigh) && v >= ds.alarmHigh) color = theme.alarm;
  else if (norm > 0.85) color = theme.accent;

// Segmented fill, bottom-up.
  const SLICES = 20;
  const sliceH = (th - 4) / SLICES;
  const filled = Math.round(norm * SLICES);
  for (let i = 0; i < filled; ++i) {
    ctx.fillStyle = color;
    ctx.fillRect(tx + 2, ty + th - (i + 1) * sliceH - 2, tw - 4, sliceH - 1);
  }

ctx.strokeStyle = theme.widget_border;
  ctx.lineWidth = 1;
  ctx.strokeRect(tx + 0.5, ty + 0.5, tw - 1, th - 1);

// Numeric readout below the tank.
  ctx.fillStyle = theme.widget_text;
  ctx.font = "bold 16px sans-serif";
  ctx.textAlign = "center";
  ctx.textBaseline = "alphabetic";
  ctx.fillText(v.toFixed(1) + " " + (ds.units || ""), w / 2, h - 10);

ctx.textAlign = "start";
}
```

### Polar bug indicator

Two datasets, bearing in degrees and range in 0..1, plotted as a marker on a polar grid. Each `arc()` is preceded by a `moveTo()` to its start point.

```javascript
function paint(ctx, w, h) {
  ctx.fillStyle = theme.widget_base;
  ctx.fillRect(0, 0, w, h);

if (datasets.length < 2) return;

const cx = w / 2;
  const cy = h / 2;
  const r  = Math.min(w, h) * 0.42;

// Concentric range rings.
  ctx.strokeStyle = theme.widget_border;
  ctx.lineWidth   = 1;
  for (let i = 1; i <= 4; ++i) {
    const rr = (r * i) / 4;
    ctx.beginPath();
    ctx.moveTo(cx + rr, cy);
    ctx.arc(cx, cy, rr, 0, Math.PI * 2);
    ctx.stroke();
  }

// Bearing spokes every 30 degrees.
  ctx.strokeStyle = theme.widget_border;
  for (let deg = 0; deg < 360; deg += 30) {
    const a = (deg - 90) * Math.PI / 180;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + Math.cos(a) * r, cy + Math.sin(a) * r);
    ctx.stroke();
  }

// Marker.
  const bearing = datasets[0].value;
  const range   = Math.max(0, Math.min(1, datasets[1].value));
  const a       = (bearing - 90) * Math.PI / 180;
  const x       = cx + Math.cos(a) * r * range;
  const y       = cy + Math.sin(a) * r * range;

ctx.fillStyle = theme.widget_highlight;
  ctx.beginPath();
  ctx.moveTo(x + 6, y);
  ctx.arc(x, y, 6, 0, Math.PI * 2);
  ctx.fill();

// Readout.
  ctx.fillStyle    = theme.widget_text;
  ctx.font         = "bold 12px sans-serif";
  ctx.textAlign    = "center";
  ctx.textBaseline = "alphabetic";
  ctx.fillText(bearing.toFixed(0) + "°  /  " + (range * 100).toFixed(0) + "%",
               cx, h - 10);
  ctx.textAlign = "start";
}
```

### A diagonal line crosses the arc

`arc()` does not start a new subpath. Immediately after `beginPath()` the path cursor is at the implicit origin (0, 0); the first `arc()` call connects that origin to the arc's start with an implicit `lineTo`. A subsequent `stroke()` strokes the chord; `fill()` encloses it; `clip()` removes a wedge from the clipping region.

Add a `moveTo()` to the arc's start point:

```javascript
ctx.beginPath();
ctx.moveTo(cx + Math.cos(startA) * r, cy + Math.sin(startA) * r);
ctx.arc(cx, cy, r, startA, endA);
ctx.stroke();
```

For full circles, `moveTo(cx + r, cy)` is sufficient.

```javascript
const traces = [];
function onFrame() {
  while (traces.length < datasets.length) traces.push([]);
  for (let i = 0; i < datasets.length; ++i) {
    traces[i].push(datasets[i].value);
  }
}
```

### `drawImage` shows nothing

The image path resolver accepts `qrc:/` resources and paths inside the project file's directory. Other paths are rejected, and a rejected path is silently skipped: nothing is drawn and no exception is raised. Confirm the resource path or that the file resolves under the project directory.

## Recommendations

## The decoder script

The script defines one global object named `decoder` with three members:

```javascript
decoder = {
  rows: ["bytes", "packets"],
  classes: [
    {name: "payload", color: "#59a14f"},
    {name: "newline", color: "#e15759"}
  ],
  decode: function(bytes, offset, ctx, size) {
    const b = new Uint8Array(bytes)
    let i = 0
    while (i < size) {
      const start = i
      while (i < size && b[i] !== 0x0A) ++i
      if (i >= size) return start
      ctx.annotate(offset + start, offset + i - 1, 1, 0,
                   [(i - start) + " bytes", "P"])
      ctx.annotate(offset + i, offset + i, 0, 1, ["LF", "n"])
      ++i
    }

## The lifecycle functions

```javascript
function onConnect() {
  // Runs once, just BEFORE the connection opens.
}

function setup() {
  // Runs once, right AFTER the device connects.
}

function loop() {
  // Runs every loop() interval while the device stays connected.
}
```

You may define any combination of the three. A device that streams on its own after a one-time handshake needs only `setup()`. A device that must be polled needs `loop()`. The script is restarted on each new connection, so `setup()` runs again every time you reconnect.

Top-level variables declared in the file persist across `loop()` iterations, so the script can keep counters, buffers, or a small state machine between ticks:

```javascript
var tick = 0;

function loop() {
  tick += 1;
  // ... use tick ...
}
```

### loop() pacing with delay()

By default `loop()` runs as fast as the worker can schedule it (the next call is queued only after the current one returns, so it never stacks up). Pacing matters: every I/O, table, or dashboard call in the loop crosses to the interface thread, so an unpaced loop that writes on every pass can starve the user interface. To pace it, call `delay(ms)` exactly like an Arduino sketch:

```javascript
function startHelper() {
  var dir = system.projectDir();
  if (!dir.ok)
    return;

var script = dir.result.directory + "/generator.py";
  var r = system.exec("python3", { args: ["-u", script], workingDir: dir.result.directory });
  if (!r.ok)
    r = system.exec("python", { args: ["-u", script], workingDir: dir.result.directory });
}
```

Pass `-u` (as above) when launching Python so its output is unbuffered and appears in the console line by line instead of in bursts.

Put the launch in `setup()` when Serial Studio listens for the data it generates (a UDP source), and in `onConnect()` when Serial Studio connects to it as a client (a TCP socket or a Modbus master), because the server has to be listening before the connection is opened.

### Staleness watchdog

`ageMs` makes a communication-loss watchdog short: no clock mixing, no timestamp bookkeeping in the parser. Mark the failure state in the Variables tables, then `refreshDashboard()` renders it without waiting for a frame:

```javascript
var commLost = false;

function loop() {
  var r = io.getLatestFrame();
  var stale = r.ok && r.result.hasData && r.result.ageMs > 1000;

if (stale && !commLost) {
    commLost = true;
    tableSet("BRD-1", "boot_selftest", 0xCC);  // sensor transforms show "Comm Loss"
    refreshDashboard();
    notifyCritical("Watchdog", "No frames for " + r.result.ageMs + " ms");
  } else if (!stale && commLost) {
    commLost = false;
    notifyInfo("Watchdog", "Communication restored");
  }

delay(100);
}
```

### ensureDashboard(spec): declarative widgets

`ensureDashboard(spec)` makes the described dashboard exist. You state what you want; it creates only what is missing and never modifies what is already there. Calling it on every `loop()` pass with the same spec is free (the last satisfied spec is remembered), so there is no bookkeeping to write:

```javascript
ensureDashboard([
  {
    title: "Telemetry",            // group, matched by title
    widget: "multiplot",           // datagrid | multiplot | gps | none | ...
    datasets: [
      { title: "Temperature", index: 1, plot: true, units: "C" },
      { title: "Pressure",    index: 2, plot: true, gauge: true }
    ]
  }
]);
```

## Examples

### 1. BLE wake-up handshake

Many BLE devices expose a service (here `FFF0`) with separate write (`FFF1`) and notify (`FFF2`) characteristics, and only start streaming after a command sequence is written. The service and notify characteristic are chosen on the BLE source and saved with the project; the driver wires them on connect, so the control loop only writes the enable sequence. Readings then arrive through the frame parser like any other data.

```javascript
function setup() {
  var cmds = ["0102030405", "0607080900", "0A0B0C0D0E"];
  for (var i = 0; i < cmds.length; ++i) {
    var r = io.ble.writeCharacteristic("fff1", cmds[i], SerialStudio.Hex);
    if (!r.ok)
      console.log("Handshake step " + i + " failed: " + r.error);
  }
}
```

A device that disconnects when idle gets a heartbeat byte every second.

```javascript
function loop() {
  io.writeData("00", SerialStudio.Hex);   // single 0x00 byte
  delay(1000);
}
```

### 3. Polling a request / response sensor

Some sensors answer only when asked. Send the query, wait, and let the reply come back through the parser as a normal frame.

```javascript
function loop() {
  io.writeData("READ\r\n", SerialStudio.Text);
  delay(200);
}
```

### 4. Timed startup sequence in setup()

A device that needs its init commands spaced out can use `delay()` between them, right inside `setup()`.

```javascript
function setup() {
  var cmds = ["BEGIN\n", "MODE 1\n", "START\n"];
  for (var i = 0; i < cmds.length; ++i) {
    io.writeData(cmds[i], SerialStudio.Text);
    delay(250);
  }
}
```

### 5. Guarding on connection state

`setup()` runs after the connection is open, but you can still confirm before acting, which is useful in `loop()` if the device may drop mid-session.

```javascript
function loop() {
  var status = io.getStatus();
  if (!status.ok || !status.result.isConnected)
    return;

io.writeData("POLL", SerialStudio.Text);
}
```

### 6. Self-building dashboard

A logger that streams a variable number of comma-separated channels gets a plotted dataset per channel, created the moment a new channel first appears. Widgets that already exist are left alone, so the script is safe to leave running.

```javascript
function loop() {
  var f = newFrame();
  if (!f) { delay(100); return; }

var spec = { title: "Telemetry", widget: "multiplot", datasets: [] };
  for (var i = 0; i < f.values.length; ++i)
    spec.datasets.push({ title: "Channel " + (i + 1), index: i + 1, plot: true });

ensureDashboard([spec]);
  delay(100);
}
```

### 7. Bringing a serial device up again

A UART source with a [Connection Sequence](Drivers-UART.md#connection-sequence) runs it on every connect, before `setup()`. A device that resets itself while the port stays open, for example on a supply dip, goes silent until it is brought up again. The loop below watches the frame age and re-runs the sequence on the open port; `io.uart.sendBreak(55)` alone serves a device that needs only a BREAK reset.

```javascript
function loop() {
  var latest = io.getLatestFrame();
  if (latest.ok && latest.result.hasData && latest.result.ageMs > 3000) {
    var r = io.uart.runSequence();
    if (!r.ok)
      console.log("Re-run refused: " + r.error);

delay(5000);
    return;
  }

delay(500);
}
```

`io.uart.runSequence()` returns as soon as the run starts, so it never counts against the runtime watchdog; the sequence reports its outcome in the console. Give it time with `delay()` before checking again, longer than the sequence's time budget. Both calls take an optional `{ sourceId: n }` for a Device other than source 0.

**Lua: declare `local` at the top of the file:**

```lua
local alpha = 0.1
local ema

function transform(value)
  if ema == nil then
    ema = value
  end

ema = alpha * value + (1 - alpha) * ema
  return ema
end
```

`alpha` and `ema` are chunk locals. Lua captures them as upvalues of the `transform` closure, so they survive between calls and they're private to this dataset. Another dataset on the same source with its own `local ema` won't see or overwrite this one.

**JavaScript: declare `var` at the top of the file:**

```javascript
var alpha = 0.1;
var ema;

function transform(value) {
  if (ema === undefined)
    ema = value;

ema = alpha * value + (1 - alpha) * ema;
  return ema;
}
```

Serial Studio wraps every JavaScript transform in an IIFE at compile time, so top-level `var` declarations are scoped to that dataset's closure, not the shared engine's global object. You get the same isolation as Lua without any extra effort.

### What NOT to do

In JavaScript, avoid bare globals: an implicit global is written to the shared engine's global object and will collide with other datasets on the same source. In Lua each dataset chunk gets its own private environment, so a bare global stays isolated per dataset and won't collide. Declaring `local` is still recommended in Lua for clarity and to match the JavaScript rule:

```lua
-- Lua: this works (ema is isolated to this dataset), but local is clearer
function transform(value)
  ema = ema or value
  ema = 0.1 * value + 0.9 * ema
  return ema
end
```

```javascript
// WRONG in JavaScript: ema without var is an implicit global
// on the shared engine, so another dataset with the same mistake
// would clobber it. Always declare var at the top.
function transform(value) {
  if (typeof ema === 'undefined') ema = value;
  ema = 0.1 * value + 0.9 * ema;
  return ema;
}
```

Always declare stateful variables with `local`/`var` at the top of the file. It also makes the code easier to read: someone scanning the top of the transform can see at a glance which variables carry state.

**Lua example: scale a voltage reading by a project-wide calibration factor:**

```lua
function transform(value)
  local k = tableGet("calibration", "voltage_scale")  -- constant
  return value * (k or 1.0)
end
```

**JavaScript example: same idea.**

```javascript
function transform(value) {
  var k = tableGet("calibration", "voltage_scale");
  return value * (k !== undefined ? k : 1.0);
}
```

**Writing to a computed variable. One transform publishes, another consumes:**

```lua
-- Dataset 10 (processed first): publish the total current
function transform(value)
  tableSet("runtime", "total_current", value)
  return value
end
```

```javascript
function transform(value, info) {
  // info.frameNumber : number
  // info.sourceId    : number
  // info.timestampMs : number
  return value;
}
```

`info.timestampMs` is a **monotonic** millisecond counter taken from the OS steady clock. It increases between consecutive frames but is not wall-clock time and does not match `Date.now()`. Use it for deltas (`info.timestampMs - lastTs`), not for "what time is it now".

`info.frameNumber` is per-source and restarts at 1 after a disconnect or project reload.

### Example: rate-limit a control update

A transform that nudges the device's setpoint, but no more than ten times per second regardless of frame rate:

### Lua example: PWM controller

```lua
local kp = 4.0
local setpoint = 25.0

function transform(sensor_temp)
  local error = setpoint - sensor_temp
  local pwm = math.max(0, math.min(255, kp * error + 128))
  deviceWrite(string.format("PWM=%d\n", math.floor(pwm + 0.5)))
  return sensor_temp
end
```

The transform returns the raw temperature unchanged (so the dashboard still shows the measured value) and writes the computed PWM duty cycle back on every frame.

### JavaScript example: alarm latch

```javascript
let triggered = false;

function transform(value) {
  if (!triggered && value > 100) {
    const r = deviceWrite("ALARM=1\n");
    if (r.ok) triggered = true;
    else console.warn("alarm write failed:", r.error);
  }
  return value;
}
```

